create table if not exists public.sync_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),refresh_request_id uuid,trigger_type text not null check(trigger_type in('AUTOMATIC','MANUAL')),status text not null check(status in('QUEUED','RUNNING','SUCCESS','FAILED','SKIPPED_ALREADY_RUNNING')),requested_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,duration_ms bigint,agent_id text,connector_version text,batch_id uuid,orders_count integer not null default 0,workbank_count integer not null default 0,stock_count integer not null default 0,audit_count integer not null default 0,failure_reason text,created_at timestamptz not null default now());
create table if not exists public.sync_refresh_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),requested_by uuid,status text not null default'QUEUED'check(status in('QUEUED','RUNNING','SUCCESS','FAILED','SKIPPED_ALREADY_RUNNING')),requested_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,sync_run_id uuid references public.sync_runs(id),failure_reason text);
alter table public.sync_runs add constraint sync_runs_refresh_request_id_fkey foreign key(refresh_request_id)references public.sync_refresh_requests(id);
create unique index sync_refresh_one_active_idx on public.sync_refresh_requests(organization_id)where status in('QUEUED','RUNNING');create index sync_runs_recent_idx on public.sync_runs(organization_id,requested_at desc);
alter table public.sync_agent_heartbeat add column if not exists last_sync_attempt_at timestamptz;alter table public.sync_agent_heartbeat add column if not exists last_success_at timestamptz;alter table public.sync_agent_heartbeat add column if not exists next_expected_sync_at timestamptz;alter table public.sync_agent_heartbeat add column if not exists current_run_id uuid;
alter table public.sync_runs enable row level security;alter table public.sync_refresh_requests enable row level security;revoke all on public.sync_runs,public.sync_refresh_requests from anon,authenticated;grant select,insert,update on public.sync_runs,public.sync_refresh_requests to service_role;
create or replace function public.claim_sync_work(p_organization_id uuid,p_agent_id text,p_connector_version text,p_interval_seconds integer default 300)returns table(run_id uuid,request_id uuid,trigger_type text,should_execute boolean)language plpgsql security definer set search_path=public as $$declare v_run uuid;v_request uuid;v_trigger text;v_last_auto timestamptz;begin perform pg_advisory_xact_lock(hashtextextended('sync-control:'||p_organization_id::text,0));update sync_runs set status='FAILED',completed_at=now(),duration_ms=extract(epoch from(now()-started_at))*1000,failure_reason='STALE_RUN_LEASE_EXPIRED'where organization_id=p_organization_id and status='RUNNING'and started_at<now()-interval'20 minutes';update sync_refresh_requests r set status='FAILED',completed_at=now(),failure_reason='STALE_RUN_LEASE_EXPIRED'where r.organization_id=p_organization_id and r.status='RUNNING'and not exists(select 1 from sync_runs s where s.id=r.sync_run_id and s.status='RUNNING');if exists(select 1 from sync_runs where organization_id=p_organization_id and status='RUNNING')then insert into sync_runs(organization_id,trigger_type,status,requested_at,completed_at,agent_id,connector_version,failure_reason)values(p_organization_id,'AUTOMATIC','SKIPPED_ALREADY_RUNNING',now(),now(),p_agent_id,p_connector_version,'ACTIVE_RUN_EXISTS')returning id into v_run;return query select v_run,null::uuid,'AUTOMATIC'::text,false;return;end if;select id into v_request from sync_refresh_requests where organization_id=p_organization_id and status='QUEUED'order by requested_at limit 1 for update skip locked;if v_request is not null then v_trigger:='MANUAL';else select max(requested_at)into v_last_auto from sync_runs where organization_id=p_organization_id and trigger_type='AUTOMATIC'and status in('RUNNING','SUCCESS','FAILED');if v_last_auto is not null and v_last_auto>now()-make_interval(secs=>greatest(60,p_interval_seconds))then return;end if;v_trigger:='AUTOMATIC';end if;insert into sync_runs(organization_id,refresh_request_id,trigger_type,status,requested_at,started_at,agent_id,connector_version)values(p_organization_id,v_request,v_trigger,'RUNNING',now(),now(),p_agent_id,p_connector_version)returning id into v_run;if v_request is not null then update sync_refresh_requests set status='RUNNING',started_at=now(),sync_run_id=v_run where id=v_request;end if;return query select v_run,v_request,v_trigger,true;end$$;
create or replace function public.finish_sync_work(p_run_id uuid,p_status text,p_batch_id uuid,p_duration_ms bigint,p_orders integer,p_workbank integer,p_stock integer,p_audit integer,p_failure text default null)returns void language plpgsql security definer set search_path=public as $$declare v_request uuid;begin if p_status not in('SUCCESS','FAILED')then raise exception'INVALID_SYNC_STATUS';end if;update sync_runs set status=p_status,completed_at=now(),duration_ms=p_duration_ms,batch_id=p_batch_id,orders_count=coalesce(p_orders,0),workbank_count=coalesce(p_workbank,0),stock_count=coalesce(p_stock,0),audit_count=coalesce(p_audit,0),failure_reason=left(p_failure,1000)where id=p_run_id and status='RUNNING'returning refresh_request_id into v_request;if v_request is not null then update sync_refresh_requests set status=p_status,completed_at=now(),failure_reason=left(p_failure,1000)where id=v_request;end if;end$$;
revoke all on function public.claim_sync_work(uuid,text,text,integer),public.finish_sync_work(uuid,text,uuid,bigint,integer,integer,integer,integer,text)from public,anon,authenticated;grant execute on function public.claim_sync_work(uuid,text,text,integer),public.finish_sync_work(uuid,text,uuid,bigint,integer,integer,integer,integer,text)to service_role;
